"""Flow rules (docs/FLOW_RULES_PLAN_2026-09-27.md), operator order 2026-09-27, live without a trial.

1. Delta: a break counts only when buyers (long) / sellers (short) have been the aggressors since 09:30.
2. Velocity: a break counts only when trades arrive much faster than normal as it happens.
3. Macro veto: no long while SPY or the sector ETF is falling, no short while either is rising.
4. Absorption exit: once a trade has been +0.5R, exit when the last 30 s of tape turns hard against it.

Rules 1 and 2 run inside both scanner paths (scanner.scan_symbol and orbproc.SymbolReducer) through the
DeltaState / VelocityState below, so the two paths share one implementation. Rules 3 and 4 fetch from the
relay. Top-level imports stay at config only: adaptive imports core, and core imports this module.
"""
import json, math, urllib.parse, urllib.request
from datetime import datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo

from . import config

ET = ZoneInfo("America/New_York")

# Conditions whose price is not a live aggressor print against the current quote. Volume-only prints
# (the scanner's NOT_PRICE, minus odd lots "I", which ARE real aggressive executions) and auction/cross
# prints: "O" opening prints, "Q" official open, "5" reopening, "6" closing, "X" cross.
# The scanner's BAD set ("W","4","B","C","T") is already dropped before a trade reaches this module.
# "L" late reports, "G" bunched sold and "9" corrected consolidated close: real prints, but not a current
# aggressor against the quote in force.
NOT_AGGRESSOR = {"V", "7", "P", "U", "Z", "H", "M", "N", "O", "Q", "5", "6", "X", "L", "G", "9"}


def _finite(v):
    try:
        v = float(v)
    except (TypeError, ValueError):
        return None
    return v if math.isfinite(v) else None


def delta_eligible(conditions):
    return not (set(conditions or []) & NOT_AGGRESSOR)


def classify(price, bid, ask, last_px, last_side):
    """+1 buy, -1 sell, 0 unclassified. Quote rule first (at/above ask buy, at/below bid sell, above/below
    mid), tick rule at the exact mid (up buy, down sell, unchanged repeats the previous side)."""
    if price is None or bid is None or ask is None or not (0 < bid < ask):
        return 0
    if price >= ask:
        return 1
    if price <= bid:
        return -1
    mid = (bid + ask) / 2.0
    if price > mid:
        return 1
    if price < mid:
        return -1
    if last_px is None:
        return 0
    if price > last_px:
        return 1
    if price < last_px:
        return -1
    return last_side or 0


def delta_pass(direction, ratio):
    if ratio is None:
        return False
    if direction == "long":
        return ratio >= config.DELTA_MIN
    if direction == "short":
        return ratio <= -config.DELTA_MIN
    return False


class DeltaState:
    """Cumulative buy/sell aggressor shares since 09:30. O(1) state."""
    __slots__ = ("buy", "sell", "last_px", "last_side")

    def __init__(self):
        self.buy = 0
        self.sell = 0
        self.last_px = None
        self.last_side = 0

    def add(self, price, size, conditions, quote):
        """quote: the prevailing quote dict (bp/ap) or None. Returns the side it booked."""
        if not delta_eligible(conditions):
            return 0
        price, size = _finite(price), _finite(size)
        if price is None or size is None or price <= 0 or size <= 0:
            return 0
        bid = _finite(quote.get("bp")) if quote else None
        ask = _finite(quote.get("ap")) if quote else None
        side = classify(price, bid, ask, self.last_px, self.last_side)
        if side > 0:
            self.buy += int(size)
        elif side < 0:
            self.sell += int(size)
        if side:
            # the tick rule compares against the previous CLASSIFIED trade only
            self.last_px = price
            self.last_side = side
        return side

    def ratio(self):
        vol = self.buy + self.sell
        return (self.buy - self.sell) / vol if vol > 0 else None

    def to_list(self):
        return [self.buy, self.sell, self.last_px, self.last_side]

    @classmethod
    def from_list(cls, payload):
        st = cls()
        st.buy, st.sell, st.last_px, st.last_side = int(payload[0]), int(payload[1]), payload[2], int(payload[3])
        return st


class VelocityState:
    """Trade counts per whole epoch second, the last WINDOW seconds only."""
    __slots__ = ("counts",)
    WINDOW = 2 + 60 + 2      # burst + base + slack

    def __init__(self):
        self.counts = {}

    def add(self, ts):
        sec = int(ts.timestamp() // 1)
        self.counts[sec] = self.counts.get(sec, 0) + 1
        if len(self.counts) > self.WINDOW:
            floor = sec - self.WINDOW
            for k in [k for k in self.counts if k <= floor]:
                del self.counts[k]

    def measure(self, ts):
        """(burst_trades, ratio) at the trade stamped ts, which must already be added. ratio None = no base."""
        sec = int(ts.timestamp() // 1)
        burst = sum(self.counts.get(sec - i, 0) for i in range(config.VELOCITY_BURST_S))
        base_n = sum(self.counts.get(sec - config.VELOCITY_BURST_S - i, 0) for i in range(config.VELOCITY_BASE_S))
        burst_rate = burst / float(config.VELOCITY_BURST_S)
        base_rate = base_n / float(config.VELOCITY_BASE_S)
        ratio = (burst_rate / base_rate) if base_rate > 0 else None
        return burst, ratio

    def to_list(self):
        return sorted([k, v] for k, v in self.counts.items())

    @classmethod
    def from_list(cls, payload):
        st = cls()
        st.counts = {int(k): int(v) for k, v in payload}
        return st


def velocity_pass(burst, ratio):
    if burst < config.VELOCITY_MIN_TRADES:
        return False
    return ratio is None or ratio >= config.VELOCITY_MIN_RATIO


def entry_rules_on():
    """Rules 1/2 add event and card fields only while at least one of them is on, so both off = the exact
    pre-rule card."""
    return bool(config.DELTA_RULE or config.VELOCITY_RULE)


class CrossState:
    """Rule 2 is judged AS PRICE HITS THE FENCE. An excursion starts on the first print past the fence (the
    previous price-eligible print was inside the range or beyond the other side). Velocity is measured on
    every print of the excursion during its first VELOCITY_BURST_S seconds and the verdict latches as passed
    once any of those prints passes; after that window the verdict is frozen, so a burst later in the same
    excursion cannot rescue a slow grind. A print back inside the range ends the excursion. Only past trades
    are ever counted (no lookahead)."""
    __slots__ = ("long", "short")

    def __init__(self):
        self.long = None      # [crossing_epoch_s, burst, ratio, passed]
        self.short = None

    def update(self, direction, velocity_state, ts):
        """Call on every price-eligible print from 09:35 (direction None = inside). Returns the excursion's
        (burst, ratio) or None when inside."""
        if direction is None:
            self.long = self.short = None
            return None
        other = "short" if direction == "long" else "long"
        setattr(self, other, None)
        now_s = ts.timestamp()
        cur = getattr(self, direction)
        if cur is None:
            burst, ratio = velocity_state.measure(ts)
            cur = [now_s, burst, ratio, velocity_pass(burst, ratio)]
            setattr(self, direction, cur)
        elif not cur[3] and now_s - cur[0] < config.VELOCITY_BURST_S:
            burst, ratio = velocity_state.measure(ts)
            cur[1], cur[2], cur[3] = burst, ratio, velocity_pass(burst, ratio)
        return cur[1], cur[2]

    def refresh(self, velocity_state, ts):
        """Call on EVERY kept trade (odd lots and volume-only prints included) after velocity_state.add: an
        open, unpassed excursion inside its first seconds is re-measured, so an odd-lot burst right after the
        crossing counts. Crossings themselves are only ever started by price-eligible prints (update)."""
        now_s = ts.timestamp()
        for cur in (self.long, self.short):
            if cur is not None and not cur[3] and now_s - cur[0] < config.VELOCITY_BURST_S:
                burst, ratio = velocity_state.measure(ts)
                cur[1], cur[2], cur[3] = burst, ratio, velocity_pass(burst, ratio)

    def to_list(self):
        return [self.long, self.short]

    @classmethod
    def from_list(cls, payload):
        st = cls()
        st.long = list(payload[0]) if payload[0] is not None else None
        st.short = list(payload[1]) if payload[1] is not None else None
        return st


def flow_fields(delta_state, crossing, direction):
    """The event fields both scanner paths add, and the combined pass. crossing = CrossState.update(...)."""
    ratio = delta_state.ratio()
    burst, vratio = crossing
    # The card records what was MEASURED, whatever the switches say, so a card built with one rule off can never
    # carry a stale "passed" into a later run with that rule on; flow_refusal re-judges with the current switches.
    d_meas = delta_pass(direction, ratio)
    v_meas = velocity_pass(burst, vratio)
    ok = (d_meas or not config.DELTA_RULE) and (v_meas or not config.VELOCITY_RULE)
    return {
        "delta_ratio": ratio,
        "delta_buy": delta_state.buy,
        "delta_sell": delta_state.sell,
        "delta_pass": d_meas,
        "burst_trades": burst,
        "velocity_ratio": vratio,
        "velocity_pass": v_meas,
    }, ok


FLOW_CARD_KEYS = ("delta_ratio", "delta_buy", "delta_sell", "burst_trades", "velocity_ratio",
                  "delta_pass", "velocity_pass")


def flow_refusal(card, pick=None):
    """Why a card must NOT trade under rules 1/2, or None. Fail-closed: a card built without the flow fields
    (a pre-deploy snapshot, a hand-built board) or one marked flow_blocked refuses while a rule is on."""
    if not entry_rules_on():
        return None
    card = card or {}
    if card.get("direction") not in ("long", "short"):
        return "card direction unknown (flow rules are on)"
    if pick is not None and pick.get("direction") != card["direction"]:
        return "pick direction differs from its flow-confirmed card"
    if "delta_pass" not in card or "velocity_pass" not in card:
        return "card has no delta/velocity reading (flow rules are on)"
    if card.get("flow_blocked"):
        if (card.get("delta_pass") is True or not config.DELTA_RULE) and \
                (card.get("velocity_pass") is True or not config.VELOCITY_RULE):
            return None     # this card's own break passes every flow rule that is on NOW (a switch went off)
        bits = []
        if config.DELTA_RULE and card.get("delta_pass") is not True:
            r = card.get("delta_ratio")
            bits.append("delta " + (f"{r:+.2f}" if isinstance(r, (int, float)) else "unknown")
                        + f" not {'+' if card.get('direction') == 'long' else '-'}{config.DELTA_MIN:.2f} its way")
        if config.VELOCITY_RULE and card.get("velocity_pass") is not True:
            bits.append(f"no trade-speed spike at the fence ({card.get('burst_trades')} trades in "
                        f"{config.VELOCITY_BURST_S}s)")
        return "no break passed the flow rules" + (": " + "; ".join(bits) if bits else "")
    if config.DELTA_RULE and card.get("delta_pass") is not True:
        return "delta did not confirm the break"
    if config.VELOCITY_RULE and card.get("velocity_pass") is not True:
        return "no trade-speed spike at the fence"
    return None


