def _relay_get(path, params, timeout):
    """One relay read with the shared client: 2 attempts inside a hard deadline, and cache=False, because a
    60-second-old fallback page must never feed a veto or an exit."""
    import time as _t
    from . import scanner
    return scanner.get_relay_client().get(path, params=params, is_meta=False, max_retries=2, cache=False,
                                          deadline=_t.monotonic() + timeout)


def _now():
    from . import shim as core
    return core.now_et()


def _parse_ts(raw):
    from .ticks import _ts as parse_market_timestamp
    return parse_market_timestamp(raw)


# ---- rule 3: macro veto ----------------------------------------------------------------------------------
def sector_of(sym):
    from . import adaptive
    return adaptive.SECTOR_MAP.get(sym)


def fetch_macro_moves(etfs, now=None, bars=None):
    """{etf: move_pct or None}. None = unverified (missing 09:30 bar, stale last bar, bad data).
    bars may be injected ({etf: [bar,...]}) by tests and research."""
    now = (now or _now()).astimezone(ET)
    open_dt = now.replace(hour=9, minute=30, second=0, microsecond=0)
    etfs = sorted(set(etfs))
    out = {e: None for e in etfs}
    if bars is None:
        import time as _t
        deadline = _t.monotonic() + config.MACRO_TIMEOUT_S
        bars = {}
        token = None
        seen = set()
        for _ in range(10):
            left = deadline - _t.monotonic()
            if left <= 0:
                raise TimeoutError("macro bars over their read budget")
            params = {"symbols": ",".join(etfs), "timeframe": "1Min",
                      "start": open_dt.astimezone(timezone.utc).isoformat(),
                      "end": now.astimezone(timezone.utc).isoformat(), "feed": "sip", "limit": 10000}
            if token:
                params["page_token"] = token
            page = _relay_get("/v2/stocks/bars", params, left)
            if _t.monotonic() >= deadline:
                raise TimeoutError("macro bars over their read budget")
            if not isinstance(page, dict) or not isinstance(page.get("bars"), (dict, type(None))):
                raise ValueError("malformed bars page")
            for sym, rows in (page.get("bars") or {}).items():
                bars.setdefault(sym, []).extend(rows or [])
            token = page.get("next_page_token")
            if not token:
                break
            if not isinstance(token, str) or token in seen:
                raise ValueError("repeated or invalid macro page token")
            seen.add(token)
        else:
            raise ValueError("bars pagination exceeded")
    for etf in etfs:
        done = []
        for bar in bars.get(etf) or []:
            try:
                t = _parse_ts(bar["t"]).astimezone(ET)
                o, c = _finite(bar.get("o")), _finite(bar.get("c"))
            except (KeyError, TypeError, ValueError):
                continue
            if o is None or c is None or o <= 0 or c <= 0:
                continue
            if t < open_dt or t + timedelta(minutes=1) > now:
                continue                     # before the open, or the minute is still forming
            done.append((t, o, c))
        done.sort()
        if not done or done[0][0] != open_dt:
            continue
        if (now - (done[-1][0] + timedelta(minutes=1))).total_seconds() > config.MACRO_MAX_STALE_S:
            continue
        out[etf] = (done[-1][2] / done[0][1] - 1.0) * 100.0
    return out


def trend(move_pct):
    move_pct = _finite(move_pct)
    if move_pct is None:
        return None
    if move_pct > config.MACRO_DEADBAND_PCT:
        return "up"
    if move_pct < -config.MACRO_DEADBAND_PCT:
        return "down"
    return "flat"


def macro_etfs(sym):
    sector = sector_of(sym)
    return ["SPY"] + ([sector] if sector else [])


def macro_refusal(sym, direction, moves):
    """Why a pick must NOT trade under the macro veto, or None when it may. Fail-closed on missing data."""
    if direction not in ("long", "short"):
        return "pick direction unknown"
    against = "down" if direction == "long" else "up"
    for etf in macro_etfs(sym):
        t = trend((moves or {}).get(etf))
        if t is None:
            return f"{etf} move since 09:30 could not be verified"
        if t == against:
            return f"{etf} is {t} {moves[etf]:+.2f}% since 09:30, against a {direction}"
    return None


def macro_refusals(picks, now=None, bars=None):
    """{symbol: reason or None} for a batch, one relay call. A fetch failure refuses every pick."""
    etfs = set()
    for p in picks:
        etfs.update(macro_etfs(p["symbol"]))
    if not etfs:
        return {}
    try:
        moves = fetch_macro_moves(etfs, now=now, bars=bars)
    except Exception as exc:
        why = f"sector/SPY bars unavailable ({type(exc).__name__})"
        return {p["symbol"]: why for p in picks}
    return {p["symbol"]: macro_refusal(p["symbol"], p.get("direction"), moves) for p in picks}


# ---- rule 4: absorption exit -----------------------------------------------------------------------------
def _window_rows(kind, sym, start, end, deadline):
    """Every page of a tape window inside ONE absolute monotonic deadline."""
    import time as _t
    rows, token, seen = [], None, set()
    for _ in range(config.ABSORPTION_MAX_PAGES):
        left = deadline - _t.monotonic()
        if left <= 0:
            raise TimeoutError(f"{kind} window over its read budget")
        params = {"start": start.astimezone(timezone.utc).isoformat(),
                  "end": end.astimezone(timezone.utc).isoformat(),
                  "limit": 10000, "feed": "sip", "sort": "asc"}
        if token:
            params["page_token"] = token
        page = _relay_get(f"/v2/stocks/{urllib.parse.quote(sym)}/{kind}", params, min(config.ABSORPTION_TIMEOUT_S, left))
        if not isinstance(page, dict) or not isinstance(page.get(kind), (list, type(None))):
            raise ValueError(f"malformed {kind} page")
        rows.extend(page.get(kind) or [])
        token = page.get("next_page_token")
        if not token:
            return rows
        if not isinstance(token, str) or token in seen:
            raise ValueError("repeated page token")
        seen.add(token)
    raise ValueError(f"{kind} window needs more than {config.ABSORPTION_MAX_PAGES} pages")


def window_delta(trades, quotes, start=None, end=None, quote_start=None):
    """(ratio, classified_trades) for a tape window, the same classifier as the entry rule. Only trades stamped
    inside [start, end] with a positive price and size count; quotes must be positive and not crossed, and no
    later than end. Anything the relay returns outside the window is ignored, never classified."""
    BAD = {"W", "4", "B", "C", "T"}
    ev = []
    for q in quotes or []:
        try:
            bp, ap = _finite(q.get("bp")), _finite(q.get("ap"))
            key = _parse_key(q["t"])
            if (end is not None and key[0] > end) or (quote_start is not None and key[0] < quote_start):
                continue
            if bp and ap and 0 < bp < ap:
                ev.append((key, 1, "q", q))
        except (KeyError, TypeError, ValueError, AttributeError):
            continue
    for t in trades or []:
        try:
            if set(t.get("c") or []) & BAD:
                continue
            p, sz = _finite(t.get("p")), _finite(t.get("s"))
            if p is None or sz is None or p <= 0 or sz <= 0:
                continue
            key = _parse_key(t["t"])
            if (start is not None and key[0] < start) or (end is not None and key[0] > end):
                continue
            ev.append((key, 0, "t", t))
        except (KeyError, TypeError, ValueError, AttributeError):
            continue
    ev.sort(key=lambda r: (r[0], r[1]))
    st, quote, n = DeltaState(), None, 0
    for _k, _p, kind, row in ev:
        if kind == "q":
            quote = row
        elif st.add(row.get("p"), row.get("s"), row.get("c"), quote):
            n += 1
    return st.ratio(), n


def _parse_key(raw):
    from .ticks import _ts_key
    return _ts_key(raw)


def absorption_check(sym, direction, now=None, trades=None, quotes=None):
    """{'fire': bool, 'ratio', 'trades', 'error'}. Never raises. trades/quotes may be injected. Both reads
    share one absolute deadline (ABSORPTION_READ_BUDGET_S)."""
    import time as _t
    now = (now or _now()).astimezone(ET)
    start = now - timedelta(seconds=config.ABSORPTION_WINDOW_S)
    deadline = _t.monotonic() + config.ABSORPTION_READ_BUDGET_S
    try:
        if trades is None:
            trades = _window_rows("trades", sym, start, now, deadline)
        quote_start = start - timedelta(seconds=5)   # so the window's first trades have a prevailing quote
        if quotes is None:
            quotes = _window_rows("quotes", sym, quote_start, now, deadline)
        ratio, n = window_delta(trades, quotes, start=start, end=now, quote_start=quote_start)
    except Exception as exc:
        return {"fire": False, "ratio": None, "trades": 0, "error": f"{type(exc).__name__}: {str(exc)[:120]}"}
    fire = False
    if ratio is not None and n >= config.ABSORPTION_MIN_TRADES:
        fire = ratio <= -config.ABSORPTION_DELTA if direction == "long" else ratio >= config.ABSORPTION_DELTA
    return {"fire": bool(fire), "ratio": ratio, "trades": n, "error": None}


_ABS_STATS = {"day": None, "checks": 0, "blind": 0}


def _abs_health(results):
    try:
        day = _now().date().isoformat()
        if _ABS_STATS["day"] != day:
            _ABS_STATS.update(day=day, checks=0, blind=0)
        _ABS_STATS["checks"] += len(results)
        _ABS_STATS["blind"] += sum(1 for r in results.values() if r.get("error"))
        import data_health
        data_health.record("absorption_exit", "Absorption exit", "ok",
                           f"Checked the tape {_ABS_STATS['checks']} times today on trades up +{config.ABSORPTION_ARM_R}R; "
                           f"{_ABS_STATS['blind']} checks could not read the tape in time and were skipped.")
    except Exception:
        pass


def _absorption_worker(sym, direction, now):
    res = absorption_check(sym, direction, now)
    _abs_health({sym: res})
    return res


def fresh_read(res, now):
    """True only for a read whose window ended at most ABSORPTION_MAX_RESULT_AGE_S before now. Checked again
    right before the supervisor acts, because an earlier exit in the same pass can take seconds."""
    asof = (res or {}).get("asof")
    if asof is None:
        return False
    age = (now - asof).total_seconds()
    return 0 <= age <= config.ABSORPTION_MAX_RESULT_AGE_S


class AbsorptionReader:
    """Background tape reads for the absorption exit. The supervisor NEVER waits on the tape: request() only
    schedules a read (one per symbol in flight, a bounded pool of workers) and take_fresh() hands back the
    reads that have already finished, dropping any whose window ended more than ABSORPTION_MAX_RESULT_AGE_S
    ago. A read therefore acts on the pass after it was requested (~5 s)."""

    def __init__(self, max_workers=4):
        import threading
        self._lock = threading.Lock()
        self._pool = None
        self._max = max_workers
        self._inflight = {}
        self._done = {}

    def request(self, sym, direction, now=None):
        from concurrent.futures import ThreadPoolExecutor
        now = (now or _now()).astimezone(ET)
        with self._lock:
            if sym in self._inflight:
                return False
            if self._pool is None:
                self._pool = ThreadPoolExecutor(max_workers=self._max, thread_name_prefix="absorption")
            fut = self._pool.submit(_absorption_worker, sym, direction, now)
            self._inflight[sym] = (fut, now, direction)
        fut.add_done_callback(lambda f, s=sym: self._finish(s, f))
        return True

    def _finish(self, sym, fut):
        with self._lock:
            _f, asof, direction = self._inflight.pop(sym, (None, None, None))
            try:
                res = dict(fut.result())
            except Exception as exc:
                res = {"fire": False, "ratio": None, "trades": 0, "error": type(exc).__name__}
            res.update(asof=asof, direction=direction)
            self._done[sym] = res
        # Only publishes. The health write happened on the worker thread (_absorption_worker): when the
        # future is already done, add_done_callback runs this on the CALLER's (supervisor's) thread.

    def take_fresh(self, now=None):
        now = (now or _now()).astimezone(ET)
        out = {}
        with self._lock:
            for sym in list(self._done):
                res = self._done.pop(sym)
                if fresh_read(res, now):
                    out[sym] = res
        return out


ABSORPTION = AbsorptionReader()


def status_sentence():
    on = [name for name, flag in (("delta", config.DELTA_RULE), ("velocity", config.VELOCITY_RULE),
                                  ("macro veto", config.MACRO_RULE), ("absorption exit", config.ABSORPTION_EXIT))
          if flag]
    return ("Flow rules on: " + ", ".join(on) + ".") if on else "Flow rules are all off."
